#  Persistência 
CONFIG_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cartorio_config.json")

def carregar_config():
    try:
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}

def salvar_config(tipo, pasta, numero):
    try:
        cfg = carregar_config()
        cfg[tipo] = {"pasta": pasta, "numero": numero}
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def salvar_preferencias(dados):
    try:
        cfg = carregar_config()
        cfg["_prefs"] = dados
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def carregar_preferencias():
    return carregar_config().get("_prefs", {})

def detectar_proximo_numero(pasta):
    maior = -1
    try:
        for nome in os.listdir(pasta):
            m = re.fullmatch(r"image(\d{6})", os.path.splitext(nome)[0], re.IGNORECASE)
            if m:
                n = int(m.group(1))
                if n > maior: maior = n
    except Exception:
        pass
    return maior + 1 if maior >= 0 else None

def contar_arquivos_pasta(pasta, extensoes):
    try:
        return sum(
            1 for f in os.listdir(pasta)
            if os.path.splitext(f)[1].lower() in extensoes
            and re.fullmatch(r"image\d{6}", os.path.splitext(f)[0], re.IGNORECASE)
        )
    except Exception:
        return 0

# ── PDF → PIL Image via pypdfium2 ─────────────────────────────────────────────
def pdf_para_imagem(caminho, w=160, h=150):
    try:
        import pypdfium2 as pdfium
        doc  = pdfium.PdfDocument(caminho)
        page = doc[0]
        pw, ph = page.get_size()          # API correta: get_size() retorna (w, h)
        scale  = min(w / pw, h / ph) * 2  # 2x para qualidade
        bmp    = page.render(scale=scale)
        img    = bmp.to_pil().convert("RGB")
        img.thumbnail((w, h))
        doc.close()
        return img
    except Exception:
        return None

def carregar_thumbnail(caminho, w=160, h=150):
    ext = os.path.splitext(caminho)[1].lower()
    try:
        from PIL import Image
        if ext == ".pdf":
            return pdf_para_imagem(caminho, w, h)
        img = Image.open(caminho).convert("RGB")
        img.thumbnail((w, h), Image.LANCZOS)
        return img
    except Exception:
        return None


